#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
V=OBSIDIANTI_MWNI_DOCUMENTED_RETARGET_v1.4.7
HERE="$(cd "$(dirname "$0")" && pwd)"
ENTRY="$HERE/$(basename "$0")"
ENTRY_SHA256="$(sha256sum "$ENTRY" | cut -d' ' -f1)"
WORK="$(mktemp -d "${TMPDIR:-${PREFIX:-/data/data/com.termux/files/usr}/tmp}/obs-mwni-document-v147.XXXXXXXX")"
cleanup(){ rm -rf "$WORK"; }
trap cleanup EXIT
printf 'CAMPAIGN=%s\nAUTHORITY=TERMUX_GIT_ONLY\nLAUNCHER_SHA256=%s\n' "$V" "$ENTRY_SHA256"
python3 - "$ENTRY" "$WORK/payload.tar.gz" <<'PY_EXTRACT'
import base64,hashlib,pathlib,sys
script=pathlib.Path(sys.argv[1]).read_text()
try: payload=script.split('\n__PACKET_B64_BEGIN__\n',1)[1].split('\n__PACKET_B64_END__',1)[0]
except IndexError:raise SystemExit('BLOCKED: embedded packet missing')
raw=base64.b64decode(''.join(payload.split()),validate=True)
expected='6008d5435ccc2da33e51752142a1a7f1a7ed4a2d5a3528df63b32bca0e0ed4b0'
actual=hashlib.sha256(raw).hexdigest()
if actual!=expected:raise SystemExit('BLOCKED: payload SHA-256 mismatch '+actual)
pathlib.Path(sys.argv[2]).write_bytes(raw)
print('PAYLOAD_SHA256='+actual,flush=True)
PY_EXTRACT
printf '%s  %s\n' '6008d5435ccc2da33e51752142a1a7f1a7ed4a2d5a3528df63b32bca0e0ed4b0' "$WORK/payload.tar.gz" | sha256sum -c -
mkdir -p "$WORK/packet"
tar -xzf "$WORK/payload.tar.gz" -C "$WORK/packet"
python3 "$WORK/packet/driver.py" "$WORK/packet" "$ENTRY" "$ENTRY_SHA256"
